"""GST: registration changes, returns, refunds and notices."""

GST_LOGIN = [('GST portal login', 'Username and password, or we help reset them.'), ('Digital signature or Aadhaar OTP', 'Of the authorised signatory, for verification.')]
RETURN_DOCS = [('Sales invoices', 'Or your sales register for the period.'), ('Purchase invoices', 'For input tax credit.'), ('GSTR-2B', 'We download it from the portal.'), ('Bank statement', 'For reconciliation, if needed.')] + GST_LOGIN
RETURN_STEPS = [('Collect data', 'You share sales and purchase data, or give us access to your accounting software.'),
                ('Reconcile', 'We match purchases with GSTR-2B and flag missing or mismatched invoices.'),
                ('Review', 'You approve the summary and tax payable before filing.'),
                ('File', 'We file the return and share the acknowledgement and challan.')]
NOTICE_DOCS = [('The notice or order', 'Downloaded from the portal or received by email.'), ('Returns for the period', 'GSTR-1, GSTR-3B and GSTR-9.'), ('Books of account', 'Sales and purchase registers, ledgers.'), ('Supporting documents', 'Invoices, e-way bills, contracts and payment proof.')] + GST_LOGIN[:1]

